        int dot=text.find('.');
        double result=stod(text.substr(0,dot));
        string fraction=text.substr(dot+1);
        int open=fraction.find('(');
        string nonRepeat=open<0?fraction:fraction.substr(0,open),repeat=open<0?"":fraction.substr(open+1,fraction.size()-open-2);
        double scale=pow(10.0,nonRepeat.size());
        if(!nonRepeat.empty())result+=stoll(nonRepeat)/scale;
        if(!repeat.empty())result+=stoll(repeat)/(scale*(pow(10.0,repeat.size())-1));
        return result;
    }
    public:bool isRationalEqual(string s,string t){
        return abs(value(s)-value(t))<1e-10;
